                "  <div class='flex-1 content'>\n" +
                "    <div class='flex'>\n" +
                "      <div class='grow'>\n" +
                "        <h3 class='title'>\n" +
                "          <a class='aitool' href='"+htmllang+t['url']+"' title='"+t['title']+"'>"+t['title']+tempflag+"\n" +
                "        </h3>\n" +
                "      </div>\n" +
                "      <div class='shrink'>\n" +
                "        <a href='"+t['site']+"' title='Visit Website' rel='nofollow' target='_blank' class='track-event' data-event-name='click' data-service-slug='"+t['title']+"'><i class='fa fa-external-link'></i></a>\n" +
                "      </div>\n" +
                "    </div>\n" +
                "    <p class='tagline'>\n" +
                "      "+t['description']+"\n" +
                "    </p>\n" +
                "    <div class='flex' style='justify-content: flex-end;'>\n" +
                "      <a id='favorite"+t['id']+"' onclick='getFavorite("+t['id']+", `/index.php?appid=1&appsecret=PHPCMF9E08B99B07369&api_auth_code=d41d8cd98f00b204e9800998ecf8427e&api_auth_uid=&s=api&c=module&m=favorite&app=website&id="+t['id']+"&value=1`)' class='loginBtn' data-method='loginfavorite'>\n" +
