                "<ul class='pagination'>"
            htmlpage += "<li><a href='"+htmllang+"/video/1' data-ci-pagination-page='1' class='aitool'>&lt;&lt;</a></li>"

            if (page==1){
                htmlpage += "<li><a href='"+htmllang+"/video/1' data-ci-pagination-page='1' class='aitool'>&lt;</a></li>"
            }else{
                htmlpage += "<li><a href='"+htmllang+"/video/"+(page-1)+"' data-ci-pagination-page="+(page-1)+" class='aitool'>&lt;</a></li>"
            }

